def sop_html(s):
    li=lambda a:''.join(f'<li>{x}</li>' for x in a)
    cm=s.get('cmd',[]);kinds=['Portal']+[k for k in ('CLI','PowerShell','Terraform') if any(c[0]==k for c in cm)]
    b=f'<p class="badges"><span class="lv">{LV[s["l"]]}</span>'+''.join(f'<span>{k}</span>' for k in kinds)+'</p>'
    acc=lambda t,body,o='':f'<details{o}><summary>{t}</summary>{body}</details>'
    ts=''.join('<tr><td>%s</td><td>%s</td></tr>'%tuple(x.split(' => ')) for x in s['ts'])
    ar=f'<h3>Architecture</h3><pre class="mermaid">{E(s["arch"])}</pre>' if s.get('arch') else ''
    fl=''.join('<tr><td>%s</td><td>%s</td><td>%s</td></tr>'%f for f in s.get('f',[]))
    ft=f'<h3>Field reference</h3><div class="tw"><table><tr><th>Field</th><th>Value</th><th>Explanation</th></tr>{fl}</table></div>' if fl else ''
    cs=''.join(f'<p><b>{k}</b> · {E(n)}</p><pre class="cmd">{E(c)}</pre>' for k,c,n in cm)
    d=' '.join(f'<a href="{u}" target="_blank" rel="noopener">Microsoft Learn: {u.split("/")[-1]}</a>' for u in s['d'])
    pt=s.get('part',7)
    return f'''<article class="sop" id="sop-{s['id']}"><h2>SOP: {s['t']}</h2>{b}<p class="crumbs">Azure Portal → {s['cat']} → {s['t']}</p>
<h3>Purpose</h3><p>{s['p']}</p>{'<h3>What you will create</h3><ul>'+li(s['c'])+'</ul>' if s.get('c') else ''}{'<h3>Prerequisites</h3><ul>'+li(s['pre'])+'</ul>' if s.get('pre') else ''}{ar}
<h3>Azure Portal navigation</h3><div class="crumb">{''.join(f'<span>{x}</span>' for x in s['nav'])}</div><h3>Procedure</h3><ol class="steps">{li(s['st'])}</ol>{ft}
{('<h3>Commands</h3>'+cs) if cs else ''}{acc('Security configuration','<ul>'+li(s.get('sec',['Apply least privilege and private access.']))+'</ul>')}{acc('Production considerations','<ul>'+li(s.get('prod',['Tag, monitor and back up per standards.']))+'</ul>')}
<h3>Validation</h3><ul>{li(s['v'])}</ul>{acc('Rollback and cleanup','<ul>'+li(s['rb'])+'</ul>')}{acc('Troubleshooting','<div class="tw"><table><tr><th>Symptom</th><th>Check and fix</th></tr>'+ts+'</table></div>')}
<h3>Validation checklist</h3><div class="ck">{''.join(f'<label><input type="checkbox"> {c}</label>' for c in CK)}</div>
<p>Related: <a href="#p{pt:02d}">Part {pt} concepts</a> · {d}</p></article>'''
